package com.trainingapp.data.exercise

import com.trainingapp.contract.exercise.ExerciseDto
import com.trainingapp.data.db.DataJson
import com.trainingapp.domain.exercise.Exercise
import kotlinx.serialization.builtins.ListSerializer

/** Reads the bundled global library (`exercise_library.json`, generated by `tools/exercise-seed`). */
fun interface ExerciseSeedSource {
    suspend fun read(): String
}

object ExerciseSeedParser {
    fun parse(json: String): List<Exercise> =
        DataJson.decodeFromString(ListSerializer(ExerciseDto.serializer()), json).map { Exercise.fromDto(it) }
}
